-- CPT (Channapatna) shed-partition reconciliation — derived from the Google Sheet
-- 'Feed Direction' tab (last 2 days), maintainer-directed 2026-07-26.
-- Base goat seed lumps these animals into consolidated PARENT sheds and leaves the
-- per-partition sheds inactive; the operator feed sheet works at the PARTITION grain.
-- This re-applies the partition split + activation. IDEMPOTENT (re-run safe): only rows
-- whose shed differs are touched. Scoped to Channapatna; CBE already matches and is untouched.
BEGIN;
CREATE TEMP TABLE _cpt ON COMMIT DROP AS
  SELECT location_id AS park_id, tenant_id FROM locations
  WHERE location_type='park' AND name='Channapatna';

-- (1) activate the fed partition sheds
UPDATE locations s SET status='active', updated_at=now()
FROM _cpt c WHERE s.parent_location_id=c.park_id AND s.location_type='shed'
  AND s.name IN ('Gandhi 1','Gandhi 2','Gandhi 3','Godel 1 - Part 1','Godel 1 - Part 2','Godel 1 - Part 3','Godel 1 - Part 4','Godel 2 - Part 1','Godel 2 - Part 2','Godel 2 - Part 3','Godel 2 - Part 4','Mandela 2 - Part 1','Mandela 2 - Part 10','Mandela 2 - Part 2','Mandela 2 - Part 3','Mandela 2 - Part 4','Mandela 2 - Part 5','Mandela 2 - Part 6','Mandela 2 - Part 7','Mandela 2 - Part 8','Mandela 2 - Part 9','Old Yashoda 1','Old Yashoda 2','Old Yashoda 3','Old Yashoda 4','Old Yashoda 5') AND s.status<>'active';

-- (2) deactivate the now-empty consolidated parent sheds
UPDATE locations s SET status='inactive', updated_at=now()
FROM _cpt c WHERE s.parent_location_id=c.park_id AND s.location_type='shed'
  AND s.name IN ('Gandhi','Godel 1','Godel 2','Mandela 2','Old Yashoda') AND s.status<>'inactive';

-- (3) place each animal (by RFID) into its partition shed
CREATE TEMP TABLE _place(rfid text, shed text) ON COMMIT DROP;
