UPDATE goats g SET shed_id=t.location_id, current_location_id=t.location_id,
       row_version=g.row_version+1, updated_at=now()
FROM _cpt c
JOIN _place p ON true
JOIN goat_identifiers gi ON gi.identifier_value=p.rfid AND gi.tenant_id=c.tenant_id
JOIN locations t ON t.name=p.shed AND t.location_type='shed' AND t.parent_location_id=c.park_id
WHERE g.goat_id=gi.goat_id AND g.tenant_id=c.tenant_id
  AND g.shed_id IS DISTINCT FROM t.location_id;

-- (4) breed corrections (maintainer-directed per the sheet 2026-07-26): the base goat seed
--     mislabels the breed/species of a few partitions. Scoped to the PLACED RFIDs only, so
--     pre-existing residents are untouched. Idempotent (only rows whose breed differs).
CREATE TEMP TABLE _breed(shed text, breed text, species text, breed_id uuid) ON COMMIT DROP;
INSERT INTO _breed(shed,breed,species,breed_id) VALUES
  ('Old Yashoda 5','Beetal','goat','00000000-0000-4000-8000-000000002002'),
  ('Mandela 2 - Part 10','Anantapur Sheep','sheep','00000000-0000-4000-8000-000000002006'),
  ('Gandhi 2','Anantapur Sheep','sheep','00000000-0000-4000-8000-000000002006');
UPDATE goats g SET breed=b.breed, species=b.species, breed_id=b.breed_id,
       row_version=g.row_version+1, updated_at=now()
FROM _cpt c
JOIN _place p ON true
JOIN _breed b ON b.shed=p.shed
JOIN goat_identifiers gi ON gi.identifier_value=p.rfid AND gi.tenant_id=c.tenant_id
WHERE g.goat_id=gi.goat_id AND g.tenant_id=c.tenant_id AND g.lifecycle_status='alive'
  AND (g.breed<>b.breed OR g.species<>b.species OR g.breed_id IS DISTINCT FROM b.breed_id);
COMMIT;
